using System.ComponentModel;
using System.Net.Http;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchApi(
        HttpClient httpClient,
        ILogger<ApiTools> logger,
        [Description("The full URL to fetch.")] string url,
        CancellationToken cancellationToken)
    {
        logger.LogInformation("Fetching {Url}", url);

        using var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var body = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Received {Length} chars from {Url}", body.Length, url);

        return body;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the provided text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Maximum number of sentences (default: 3).")] int? maxSentences = 3)
    {
        return new GetPromptResult
        {
            Description = "Summarization prompt",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new Content
                    {
                        Type = "text",
                        Text = $"""
                            Please summarize the following text in at most {maxSentences ?? 3} sentences.
                            Be concise and capture the key points.

                            ---
                            {text}
                            ---
                            """
                    }
                }
            ]
        };
    }
}

